/**
 * Autogenerated by feeding the context.json file to https://app.quicktype.io/
 */

export interface IContext {
  STACK_ID:           string;
  PREFIXES:           Prefixes;
  ACCOUNT:            string;
  REGION:             string;
  VPC?:               VPC;
  DNS?:               DNS;
  S3PROXY:            S3Proxy;
  WORDPRESS:          Wordpress;
  AUTOSCALING?:       boolean;
  REDIS?:             Redis;
  TAGS:               Tags;
}

export interface DNS {
  hostedZone:                string;
  crossAccountHostedZoneId?: string;
  subdomain?:                string;
  certificateARN:            string;
  cloudfront?:               Cloudfront;
}

export interface Cloudfront {
  challengeHeaderName: string;
  distributionDomainName?: string;
}

export interface VPC {
  existingVpcId?: string;
}

export interface Redis {
  cacheNodeType?: string,
  numCacheNodes?: number,
}

export interface Prefixes {
  wordpress: string;
  s3proxy:   string;
  rds:       string;
}

export interface S3Proxy {
  dockerImage:          string;
  bucketUserSecretName: string;
  OLAP:                 string;
  region:               string;
}

export interface Tags {
  Service:   string;
  Function:  string;
  Landscape: string;
  CostCenter?: string;
  Ticket?: string;
}

export interface Wordpress {
  dockerImage: string;
  env:         WordpressEnv;
  secret:      WordpressSecret;
}

export interface WordpressEnv {
  spEntityId?:       string;
  idpEntityId?:      string;
  s3ProxyHost?:      string;
  TZ?:               string;
  dbType?:           WORDPRESS_DB_TYPE;
  dbHost?:           string;
  dbUser?:           string;
  dbName?:           string;
  dbPort?:           string;
  debug?:            any;
  /**
   * Canonical WP_ENVIRONMENT_TYPE signal used by both WordPress runtime behavior
   * and this stack's derived RDS posture (durability, high availability, scaling).
   * Allowed values follow WordPress: 'local' | 'development' | 'staging' | 'production'.
   * See https://developer.wordpress.org/reference/functions/wp_get_environment_type/
   * Values outside this set are treated as 'production' by WordPress core, which can
   * leave non-production containers without robots.txt suppression, making them indexable.
   * BU stage labels (prod/test/devl/syst) belong in TAGS.Landscape, not here.
   */
  environmentType?:  'local' | 'development' | 'staging' | 'production';
}

export interface WordpressSecret {
  wpSecretArn:         string;
  spSecretArn:         string;
  fieldNames:      SecretFieldNames;
}

export interface SecretFieldNames {
  dbPassword:  string;
  configExtra: string;
  spKey:       string;
  spCert:      string;
}

export enum WORDPRESS_DB_TYPE {
  INSTANCE = 'instance',
  CLUSTER = 'cluster',
  SERVERLESS = 'serverless'
}
